export async function run(api, params) {
  const { stay_id, room, checkin, checkout, guest_name, guest_email, notes } = params;

  // Validate room exists for the stay
  const stayRes = await api.get(`/stays/${stay_id}`);
  const roomExists = stayRes.stay.rooms.some(r => r.code === room);
  if (!roomExists) {
    throw new Error(`Room type '${room}' does not exist for stay '${stay_id}'`);
  }

  // Perform booking
  const body = { room, checkin, checkout, guest_name, guest_email, notes };
  const res = await api.call("POST /stays/{stay_id}/book", { stay_id }, body);

  // Confirm booking
  const confirmRes = await api.get(`/stays/${stay_id}`);
  const booking = confirmRes.stay.bookings.find(b =>
    b.guest_email === guest_email &&
    b.checkin === checkin &&
    b.checkout === checkout
  );

  if (!booking) {
    throw new Error("Booking confirmation failed - booking not found");
  }

  return {
    bookingId: booking.id,
    stayId: stay_id,
    room,
    checkin,
    checkout,
    guestName: guest_name,
    guestEmail: guest_email,
    notes
  };
}

export async function run(api, params) {
  params = params || {};
  const required = ["stay_id", "room", "checkin", "checkout", "guest_name", "guest_email"];
  for (const k of required) {
    if (!params[k]) throw new Error("Missing required parameter: " + k);
  }
  const { stay_id, room, checkin, checkout, guest_name, guest_email, notes } = params;

  let stay;
  try {
    const res = await api.get("/stays/" + stay_id);
    stay = res && res.stay;
  } catch (e) {
    throw new Error("Could not load stay '" + stay_id + "': " + (e && e.message ? e.message : String(e)));
  }
  if (!stay) {
    throw new Error("Stay '" + stay_id + "' was not found");
  }

  const validRoom = Array.isArray(stay.rooms) && stay.rooms.some((r) => r.code === room);
  if (!validRoom) {
    throw new Error("Room code '" + room + "' is not offered at stay '" + stay_id + "'");
  }

  const body = { room, checkin, checkout, guest_name, guest_email };
  if (notes) body.notes = String(notes);

  let booking;
  try {
    booking = await api.call("POST /stays/{stay_id}/book", { stay_id }, body);
  } catch (e) {
    throw new Error("Booking rejected for stay '" + stay_id + "': " + (e && e.message ? e.message : String(e)));
  }

  return {
    action: "book_stay",
    stay_id,
    stay_name: stay.name,
    room,
    checkin,
    checkout,
    guest_name,
    guest_email,
    booking,
  };
}
